def load_mall_dataset_annotations(mall_gt_path, frames_path, num_frames=500):

    print(f"Loading Mall Dataset from {mall_gt_path}...")

    # Load the .mat file
    mat_data = scipy.io.loadmat(mall_gt_path)
    frame_data = mat_data['frame']

    annotations = {}
    total_people = 0

    print(f"Processing {num_frames} frames...")

    for frame_idx in tqdm(range(min(num_frames, len(frame_data[0])))):
        frame_name = f"seq_{frame_idx+1:06d}.jpg"

        # Get head center positions
        head_positions = frame_data[0][frame_idx][0][0][0]

        if len(head_positions) == 0:
            continue

        # Create body-sized bounding boxes
        boxes = []

        for head_pos in head_positions:
            x_center, y_center = int(head_pos[0]), int(head_pos[1])

            # Create body box:
            # - Center the box horizontally on the head
            # - Position the box so head is in upper portion (20% from top)
            x = max(0, x_center - BODY_WIDTH // 2)
            y = max(0, y_center - int(BODY_HEIGHT * 0.15))  # Head at 20% from top

            boxes.append([x, y, BODY_WIDTH, BODY_HEIGHT])

        annotations[frame_name] = boxes
        total_people += len(boxes)

    print(f"\n✓ Loaded {len(annotations)} frames")
    print(f"✓ Total people annotated: {total_people}")
    print(f"✓ Average people per frame: {total_people/len(annotations):.1f}")

    # Copy frames to raw_images directory
    print(f"\nCopying frames to {BASE_DIR}/data/raw_images/...")
    frames_copied = 0

    for frame_name in tqdm(annotations.keys()):
        src = f"{frames_path}/{frame_name}"
        dst = f"{BASE_DIR}/data/raw_images/{frame_name}"

        if os.path.exists(src):
            shutil.copy2(src, dst)
            frames_copied += 1

    print(f"✓ Copied {frames_copied} frames")

    # Save annotations
    with open(f'{BASE_DIR}/annotations/annotations.json', 'w') as f:
        json.dump(annotations, f, indent=2)

    print(f"✓ Annotations saved to {BASE_DIR}/annotations/annotations.json")

    return annotations

