def extract_samples(annotations, target_size=TARGET_SIZE):

    positive_count = 0
    negative_count = 0

    print(f"Extracting samples at size {target_size}...")

    for img_file, boxes in tqdm(annotations.items(), desc="Processing images"):
        img_path = f'{BASE_DIR}/data/raw_images/{img_file}'
        image = cv2.imread(img_path)
        image = cv2.cvtColor(image, cv2.COLOR_BGR2RGB)

        h, w = image.shape[:2]

        # Extract positive samples (bodies)
        for idx, box in enumerate(boxes):
            x, y, bw, bh = box

            # Ensure box is within boundaries
            x = max(0, x)
            y = max(0, y)
            x2 = min(w, x + bw)
            y2 = min(h, y + bh)

            if x2 > x and y2 > y:
                body_crop = image[y:y2, x:x2]
                body_crop_resized = cv2.resize(body_crop, target_size)

                save_path = f'{BASE_DIR}/data/positive_samples/pos_{img_file}_{idx}.png'
                cv2.imwrite(save_path, cv2.cvtColor(body_crop_resized, cv2.COLOR_RGB2BGR))
                positive_count += 1

        # Extract negative samples (3x more negatives)
        num_negatives = len(boxes) * 3
        neg_extracted = 0
        attempts = 0
        max_attempts = num_negatives * 5

        while neg_extracted < num_negatives and attempts < max_attempts:
            attempts += 1

            # Random location
            if w <= target_size[0] or h <= target_size[1]:
                break

            rx = np.random.randint(0, w - target_size[0])
            ry = np.random.randint(0, h - target_size[1])

            # Check overlap with body boxes
            overlap = False
            for box in boxes:
                bx, by, bw, bh = box
                # Check if rectangles overlap
                if not (rx + target_size[0] < bx or rx > bx + bw or
                       ry + target_size[1] < by or ry > by + bh):
                    overlap = True
                    break

            if not overlap:
                neg_crop = image[ry:ry+target_size[1], rx:rx+target_size[0]]
                if neg_crop.shape[:2] == (target_size[1], target_size[0]):
                    save_path = f'{BASE_DIR}/data/negative_samples/neg_{img_file}_{negative_count}.png'
                    cv2.imwrite(save_path, cv2.cvtColor(neg_crop, cv2.COLOR_RGB2BGR))
                    negative_count += 1
                    neg_extracted += 1

    print("\n" + "="*60)
    print("SAMPLE EXTRACTION COMPLETE")
    print("="*60)
    print(f"✓ Positive samples (bodies): {positive_count}")
    print(f"✓ Negative samples (background): {negative_count}")
    print(f"✓ Sample size: {target_size[0]}x{target_size[1]} pixels")
    print("="*60)

    return positive_count, negative_count

