"""Preprocessing and HOG Feature Extraction"""

def preprocess_image(image):

    if len(image.shape) == 3:
        gray = cv2.cvtColor(image, cv2.COLOR_RGB2GRAY)
    else:
        gray = image.copy()

    # NO histogram equalization
    gray = cv2.GaussianBlur(gray, (3, 3), 0)

    # Normalize to [0,1] only once
    gray = gray.astype(np.float32) / 255.0

    return gray

def extract_hog_features(image):

    # Preprocess
    preprocessed = preprocess_image(image)

    # Extract HOG features
    features = hog(
        preprocessed,
        orientations=HOG_PARAMS['orientations'],
        pixels_per_cell=HOG_PARAMS['pixels_per_cell'],
        cells_per_block=HOG_PARAMS['cells_per_block'],
        block_norm=HOG_PARAMS['block_norm'],
        transform_sqrt=HOG_PARAMS['transform_sqrt'],
        feature_vector=True
    )

    return features

def visualize_hog(image):
    preprocessed = preprocess_image(image)

    features, hog_image = hog(
        preprocessed,
        orientations=HOG_PARAMS['orientations'],
        pixels_per_cell=HOG_PARAMS['pixels_per_cell'],
        cells_per_block=HOG_PARAMS['cells_per_block'],
        block_norm=HOG_PARAMS['block_norm'],
        transform_sqrt=HOG_PARAMS['transform_sqrt'],
        visualize=True,
        feature_vector=True
    )

    hog_image_rescaled = exposure.rescale_intensity(hog_image, in_range=(0, 10))

    fig, (ax1, ax2) = plt.subplots(1, 2, figsize=(12, 6))

    ax1.imshow(preprocessed, cmap='gray')
    ax1.set_title('Preprocessed Image', fontweight='bold')
    ax1.axis('off')

    ax2.imshow(hog_image_rescaled, cmap='gray')
    ax2.set_title(f'HOG Features ({len(features)} dimensions)', fontweight='bold')
    ax2.axis('off')

    plt.tight_layout()
    plt.show()

    print(f"Feature vector length: {len(features)}")

