"""Data Augmentation"""

def augment_image(image):

    augmented = [image]

    # Horizontal flip
    flipped = cv2.flip(image, 1)
    augmented.append(flipped)

    # Brightness adjustments
    brightened = cv2.convertScaleAbs(image, alpha=1.2, beta=10)
    darkened = cv2.convertScaleAbs(image, alpha=0.8, beta=-10)
    augmented.extend([brightened, darkened])

    return augmented

def load_dataset(augment=True):
    X = []
    y = []

    print("Loading positive samples (bodies)...")
    pos_files = os.listdir(f'{BASE_DIR}/data/positive_samples')

    for file in tqdm(pos_files, desc="Processing positive samples"):
        img = cv2.imread(f'{BASE_DIR}/data/positive_samples/{file}')
        img = cv2.cvtColor(img, cv2.COLOR_BGR2RGB)

        if augment:
            augmented = augment_image(img)
            for aug_img in augmented:
                features = extract_hog_features(aug_img)
                X.append(features)
                y.append(1)
        else:
            features = extract_hog_features(img)
            X.append(features)
            y.append(1)

    print(f"✓ Loaded {sum(1 for label in y if label == 1)} positive samples")

    print("\nLoading negative samples (background)...")
    neg_files = os.listdir(f'{BASE_DIR}/data/negative_samples')

    for file in tqdm(neg_files, desc="Processing negative samples"):
        img = cv2.imread(f'{BASE_DIR}/data/negative_samples/{file}')
        img = cv2.cvtColor(img, cv2.COLOR_BGR2RGB)

        features = extract_hog_features(img)
        X.append(features)
        y.append(0)

    print(f"✓ Loaded {sum(1 for label in y if label == 0)} negative samples")

    X = np.array(X)
    y = np.array(y)

    print("\n" + "="*60)
    print("DATASET SUMMARY")
    print("="*60)
    print(f"Total samples: {len(X)}")
    print(f"Feature dimensions: {X.shape[1]}")
    print(f"Positive (bodies): {np.sum(y==1)} ({np.sum(y==1)/len(y)*100:.1f}%)")
    print(f"Negative (background): {np.sum(y==0)} ({np.sum(y==0)/len(y)*100:.1f}%)")
    print("="*60)

    return X, y

# Load dataset
