class OptimizedCrowdDetector:

    def __init__(self, model_dir):
        print(f"Loading detector from: {model_dir}")

        # Load files
        classifier_path = os.path.join(model_dir, "body_detector_svm_optimized.pkl")
        scaler_path = os.path.join(model_dir, "feature_scaler_optimized.pkl")
        config_path = os.path.join(model_dir, "config_optimized.json")

        # Check files exist
        for path in [classifier_path, scaler_path, config_path]:
            if not os.path.exists(path):
                raise FileNotFoundError(f"File tidak ditemukan: {path}")

        # Load model components
        with open(classifier_path, 'rb') as f:
            self.classifier = pickle.load(f)

        with open(scaler_path, 'rb') as f:
            self.scaler = pickle.load(f)

        with open(config_path, 'r') as f:
            config = json.load(f)

        # Set parameters
        self.window_size = tuple(config['window_size'])
        self.hog_params = config['hog_params']

        params = config['detection_params']
        self.min_confidence = params['min_confidence']
        self.nms_threshold = params['nms_threshold']
        self.step_size = params['step_size']
        self.max_boxes = params['max_boxes']
        self.min_box_area = params['min_box_area']
        self.edge_margin = params['edge_margin']
        self.min_aspect_ratio = params['min_aspect_ratio']
        self.max_aspect_ratio = params['max_aspect_ratio']

        print(f"✓ Detector loaded successfully")
        print(f"  Version: {config.get('version', 'unknown')}")
        print(f"  Min confidence: {self.min_confidence}")

    def detect(self, image):
        # Multi-scale detection
        detections, confidences = self._detect_multiscale(image)

        if len(detections) == 0:
            return [], []

        # Apply filters
        filtered = []
        for box, conf in zip(detections, confidences):
            x, y, w, h = box

            if h == 0:
                continue

            # Aspect ratio filter
            aspect_ratio = w / h
            if not (self.min_aspect_ratio <= aspect_ratio <= self.max_aspect_ratio):
                continue

            # Area filter
            if w * h < self.min_box_area:
                continue

            # Edge filter
            if not self._is_not_edge(box, image.shape):
                continue

            filtered.append((box, conf))

        if len(filtered) == 0:
            return [], []

        filtered_boxes = [d[0] for d in filtered]
        filtered_confidences = [d[1] for d in filtered]

        # Apply NMS
        final_boxes, final_confidences = self._non_max_suppression(
            filtered_boxes, filtered_confidences
        )

        # Limit boxes
        if len(final_boxes) > self.max_boxes:
            sorted_indices = np.argsort(final_confidences)[::-1][:self.max_boxes]
            final_boxes = [final_boxes[i] for i in sorted_indices]
            final_confidences = [final_confidences[i] for i in sorted_indices]

        return final_boxes, final_confidences

    def visualize(self, image, boxes, confidences=None):
        result = image.copy()

        # Draw boxes
        for i, (x, y, w, h) in enumerate(boxes):
            cv2.rectangle(result, (x, y), (x+w, y+h), (0, 255, 0), 2)

            if confidences is not None:
                label = f"{confidences[i]:.1f}"
                cv2.putText(result, label, (x, y-5),
                           cv2.FONT_HERSHEY_SIMPLEX, 0.5, (0, 255, 0), 2)

        # Add summary
        num_people = len(boxes)
        h, w = image.shape[:2]
        density = (num_people / (w * h)) * 100000

        if density < 5:
            crowd_level = "Low"
        elif density < 15:
            crowd_level = "Medium"
        elif density < 30:
            crowd_level = "High"
        else:
            crowd_level = "Very High"

        cv2.putText(result, f"People: {num_people}", (10, 30),
                   cv2.FONT_HERSHEY_SIMPLEX, 1, (0, 255, 0), 2)
        cv2.putText(result, f"Crowd: {crowd_level}", (10, 60),
                   cv2.FONT_HERSHEY_SIMPLEX, 1, (0, 255, 0), 2)
        cv2.putText(result, f"Density: {density:.1f}/100k", (10, 90),
                   cv2.FONT_HERSHEY_SIMPLEX, 1, (0, 255, 0), 2)

        return result

    # Internal methods
    def _extract_hog_features(self, image):
        """Extract HOG features"""
        if len(image.shape) == 3:
            image = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)

        features = hog(
            image,
            orientations=self.hog_params['orientations'],
            pixels_per_cell=tuple(self.hog_params['pixels_per_cell']),
            cells_per_block=tuple(self.hog_params['cells_per_block']),
            block_norm=self.hog_params['block_norm'],
            transform_sqrt=self.hog_params['transform_sqrt'],
            feature_vector=True
        )
        return features

    def _sliding_window(self, image, step_size, window_size):
        for y in range(0, image.shape[0] - window_size[1], step_size):
            for x in range(0, image.shape[1] - window_size[0], step_size):
                yield (x, y, image[y:y+window_size[1], x:x+window_size[0]])

    def _detect_single_scale(self, image, scale=1.0):
        h, w = image.shape[:2]
        resized = cv2.resize(image, (int(w * scale), int(h * scale)))

        detections = []
        confidences = []

        for (x, y, window) in self._sliding_window(resized, self.step_size, self.window_size):
            if window.shape[0] != self.window_size[1] or window.shape[1] != self.window_size[0]:
                continue

            features = self._extract_hog_features(window)
            features = self.scaler.transform([features])

            prediction = self.classifier.predict(features)[0]
            confidence = self.classifier.decision_function(features)[0]

            if prediction == 1 and confidence >= self.min_confidence:
                x_orig = int(x / scale)
                y_orig = int(y / scale)
                w_orig = int(self.window_size[0] / scale)
                h_orig = int(self.window_size[1] / scale)

                detections.append([x_orig, y_orig, w_orig, h_orig])
                confidences.append(confidence)

        return detections, confidences

    def _detect_multiscale(self, image):
        scales = [0.7, 0.85, 1.0, 1.2, 1.4]
        all_detections = []
        all_confidences = []

        for scale in scales:
            detections, confidences = self._detect_single_scale(image, scale)
            all_detections.extend(detections)
            all_confidences.extend(confidences)

        return all_detections, all_confidences

    def _is_not_edge(self, box, img_shape):
        x, y, box_w, box_h = box
        h, w = img_shape[:2]
        center_x = x + box_w // 2
        center_y = y + box_h // 2
        return (self.edge_margin < center_x < w - self.edge_margin and
                self.edge_margin < center_y < h - self.edge_margin)

    def _non_max_suppression(self, boxes, confidences):
        if len(boxes) == 0:
            return [], []

        boxes = np.array(boxes)
        confidences = np.array(confidences)

        x1 = boxes[:, 0]
        y1 = boxes[:, 1]
        x2 = boxes[:, 0] + boxes[:, 2]
        y2 = boxes[:, 1] + boxes[:, 3]

        areas = (x2 - x1 + 1) * (y2 - y1 + 1)
        idxs = np.argsort(confidences)[::-1]

        pick = []
        while len(idxs) > 0:
            i = idxs[0]
            pick.append(i)

            xx1 = np.maximum(x1[i], x1[idxs[1:]])
            yy1 = np.maximum(y1[i], y1[idxs[1:]])
            xx2 = np.minimum(x2[i], x2[idxs[1:]])
            yy2 = np.minimum(y2[i], y2[idxs[1:]])

            w = np.maximum(0, xx2 - xx1 + 1)
            h = np.maximum(0, yy2 - yy1 + 1)

            overlap = (w * h) / areas[idxs[1:]]
            idxs = np.delete(idxs, np.concatenate(([0], np.where(overlap > self.nms_threshold)[0] + 1)))

        return boxes[pick].tolist(), confidences[pick].tolist()

def load_detector(model_dir):
    return OptimizedCrowdDetector(model_dir)


MODEL_DIR = "/content/drive/MyDrive/crowd_body_detection/optimized_model_v1"
